run_cnn_predictions <- function(labeled_chunks, raster_layer, model) {
  # Runs the unlabeled sub-areas of raster_layer through a trained CNN model
  # and returns a probability map comprising the predicted probabilities
  # generated by that model.
  #
  # Args:
  #   labeled_chunks: An sf object of type POLYGON, with fields named 'id_num,'
  #     'label,' 'training,' and 'testing,' in addition to the geometry column.
  #     All chunks that are unlabeled (that is, that have NA for their 'label'
  #     value) will be run through the input model. It is intended that this is
  #     the same sf object returned by the function raster_chunking,
  #     subsequently labeled, and then passed to the generate_images function.
  #  raster_layer: The SpatRaster to which the CNN model will be applied. This
  #     should, of course, be the same SpatRaster ingested by generate_images.
  #  model: A trained CNN model. It is intended that this is a model
  #     generated by train_test_cnn.
  #
  # Returns:
  #   A SpatRaster in which each cell contains the probability assigned to it
  #   by the input model.
  
  # Make sure required packages are installed.
  terra_installed <- require(terra)
  sf_installed <- require(sf)
  png_installed <- require(png)
  magrittr_installed <- require(magrittr)
  keras_installed <- require(keras)
  tfhub_installed <- require(tfhub)
  pins_installed <- require(pins)
  tfd_installed <- require(tfdatasets)
  roc_installed <- require(pROC)
  stopifnot(terra_installed & sf_installed & png_installed &
              magrittr_installed & keras_installed & tfhub_installed &
              pins_installed & tfd_installed & roc_installed)
  
  # Make sure the input labeled_chunks has the necessary fields.
  if ('id' %in% colnames(labeled_chunks)) {
    colnames(labeled_chunks)[colnames(labeled_chunks) == 'id'] <- 'id_num'
  }
  id_present <- 'id_num' %in% colnames(labeled_chunks)
  label_present <- 'label' %in% colnames(labeled_chunks)
  train_present <- 'training' %in% colnames(labeled_chunks)
  test_present <- 'testing' %in% colnames(labeled_chunks)
  geometry_present <- 'geometry' %in% colnames(labeled_chunks)
  if ((id_present & label_present & train_present &
       test_present & geometry_present) == FALSE) {
    stop(paste0('labeled_chunks needs \'id_num\', \'label\', \'training\',',
                '\'testing\', and \'geometry\' columns'))
  }
  
  # Create a bounding polygon for each image to be created.
  centroids <- st_centroid(labeled_chunks)  # Find centroid of each chunk.
  cent_matrix <- cbind(centroids$id, st_coordinates(centroids))  # Put centroid
  # coordinates, and an ID number for each, in matrix form.
  colnames(cent_matrix) <- c('id_num', 'X', 'Y')
  image_size <- model$input_shape[[2]]
  half_image_side <- image_size / 2
  
  # Define a function to create an image boundary around each centroid.
  make_image_bounds <- function(id_num, input_matrix) {
    left <- input_matrix[id_num, 2] - half_image_side
    right <- input_matrix[id_num, 2] + half_image_side
    top <- input_matrix[id_num, 3] + half_image_side
    bottom <- input_matrix[id_num, 3] - half_image_side
    xs <- c(left, right, right, left, left)
    ys <- c(top, top, bottom, bottom, top)
    cbind(id_num, xs, ys)
  }
  
  # Apply that function to all centroids.
  print('Creating boundary boxes for the images to be created.')
  image_bound_coords <- lapply(cent_matrix[, 1],
                               make_image_bounds,
                               input_matrix = cent_matrix)
  
  # Put those results into a data frame.
  bound_coord_df <- as.data.frame(do.call(rbind, image_bound_coords))
  
  # Convert the data frame to an sf data frame.
  print('Putting those boundary boxes into an sf data frame.')
  image_bound_sf <- sfheaders::sf_polygon(bound_coord_df,
                                          x = 'xs',
                                          y = 'ys',
                                          polygon_id = 'id_num')
  image_bound_sf$label <- labeled_chunks$label
  image_bound_sf$training <- labeled_chunks$training
  image_bound_sf$testing <- labeled_chunks$testing
  
  # Make sure the CRS matches that of the input shapefile.
  st_crs(image_bound_sf) <- st_crs(labeled_chunks)
  
  # Create a directory to hold the unlabeled images.
  pred_dir <- 'for_prediction'
  dir.create(pred_dir)
  
  # The data set is so big that creating all these images, holding them all in
  # memory, and running them all through the model to generate predictions is
  # too much at once. I'm going to loop through batches of the unlabeled chunks, 
  # generating the images for each batch and running them through the model as I
  # go. Each time I finish with a batch, I'll delete the images before beginning
  # with the next one.
  cutoff_seq <- c(seq(0, nrow(image_bound_sf), 50000), nrow(image_bound_sf))
  results <- data.frame()
  for(h in 1:(length(cutoff_seq) - 1)) {
    print(paste0('Beginning image generation, batch ', h, ' of ',
                 length(cutoff_seq) - 1))
    cur_rows <- (cutoff_seq[h] + 1):(cutoff_seq[h + 1])  # row numbers of current
    # batch
    cur_chunks <- integer()  # to record chunk numbers of chunks to be run
    # through the model
    nolab.ind <- 1  # index variable
    image_id <- sprintf(paste0('%0', nchar(length(cur_rows)), 'd'),
                        1:length(cur_rows))
    for (i in cur_rows) {
      lab_val <- image_bound_sf$label[i]
      cur_num <- image_bound_sf$id_num[i]
      cur.rast <- terra::crop(raster_layer, image_bound_sf$geom[i])
      if (is.na(lab_val)) {
        png(filename = paste0(pred_dir, '/', image_id[nolab.ind], '_chunk_',
                              cur_num, '.png'),
            width = image_size, height = image_size)
        if (nlyr(raster_layer) == 1) {
          plot(cur.rast, col = gray.colors(255), mar = c(0, 0, 0, 0),
               legend = FALSE, frame.plot = FALSE, axes = FALSE)
        } else if (nlyr(raster_layer) == 3) {
          plot(cur.rast)
        }
        dev.off()
        nolab.ind <- nolab.ind + 1
        cur_chunks <- c(cur_chunks, cur_num)
      } else {
        next
      }
      print(paste0('Done ', i, ' of ', nrow(image_bound_sf), ', batch ',
                   h, ' of ', length(cutoff_seq) - 1))
    }
    print(paste0('Images for batch ', h, ' generated.'))
    
    pred_ds <- image_dataset_from_directory(
      'for_prediction/',
      label_mode = NULL,
      color_mode = 'rgb',
      image_size = c(image_size, image_size),
      shuffle = FALSE
    )
    
    # Run predictions.
    cur_probs <- model %>% predict(pred_ds)
    
    # Commenting out these lines, which would round the predicted probabilities to
    # 0 or 1, yielding binary predictions.
    # cur_probs <- new_model %>% predict(pred_ds) %>% `>`(0.5) %>% k_cast('int32')
    # cur_probs <- as.numeric(cur_probs[, 1])
    
    # Make a data frame for the predicted probabilities and associate each one
    # with the name of the image with which it's associated.
    cur_results <- data.frame(cur_chunks,
                              cur_probs)
    colnames(cur_results) <- c('id_num', 'pred_prob')
    results <- rbind(results, cur_results)
    unlink('for_prediction/*')  # Delete all the image files just generated.
  }
  
  unlink(pred_dir)  # Delete the folder for holding the image files.
  
  # Create a field in labeled_chunks to hold predicted probabilities.
  labeled_chunks$pred_prob <- numeric(length = nrow(labeled_chunks))
  
  for (i in 1:nrow(results)) {
    cur_chunk <- results$id_num[i]
    labeled_chunks[which(labeled_chunks$id_num ==
                           cur_chunk), 'pred_prob'] <- results$pred_prob[i]
    print(paste0('Done ', i, ' of ', nrow(results), ' rows.'))
  }
  
  # Make individual points (coordinates) from the centroids of the individual chunks.
  centroids <- st_centroid(labeled_chunks)
  cent_vect <- vect(centroids)
  
  # Create an empty raster to populate with the output probabilities. Resolution
  # matches the size of the chunks in labeled_chunks.
  output_res <- as.numeric(sqrt(st_area(labeled_chunks[1, ])))
  width <- xmax(raster_layer) - xmin(raster_layer)
  height <- ymax(raster_layer) - ymin(raster_layer)
  empty_map <- rast(ncol = floor(width / output_res),
                    nrow = floor(height / output_res),
                    xmin = xmin(raster_layer),
                    ymin = ymax(raster_layer) - (height - (height %% output_res)),
                    xmax = xmin(raster_layer) + (width - (width %% output_res)),
                    ymax = ymax(raster_layer),
                    crs = crs(raster_layer))
  # Fill that raster with the predicted probabilities.
  prob_map_rast <- rasterize(cent_vect, empty_map, 'pred_prob')
  
  return(prob_map_rast)
}

